0438\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u0432 \u044d\u0442\u043e\u043c \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0435 \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043d\u044b\u043c \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u043e\u043c.\n\n======================================================================\n1. \u041c\u041e\u0414\u0415\u041b\u042c \u0418 \u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u042f (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0442\u0440\u0435\u0431\u043e\u0432\u0430\u043d\u0438\u044f \u0437\u0430\u0434\u0430\u0447\u0438)\n======================================================================\n\u041c\u043e\u0434\u0435\u043b\u044c \u0434\u0430\u043d\u043d\u044b\u0445:\n  x_j = \u03a3_{k\u2208pa(j)} f_jk(x_k) + \u03a3_m \u03bb_jm\u00b7\u2113_m + e_j,  j = 1..p\n\u0433\u0434\u0435: f_jk \u2014 \u043d\u0435\u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0435 \u0430\u0434\u0434\u0438\u0442\u0438\u0432\u043d\u044b\u0435 \u0444\u0443\u043d\u043a\u0446\u0438\u0438 (\u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0435 \u0438\u0437 \u0441\u043b\u043e\u0432\u0430\u0440\u044f: sin(a\u00b7x+b), tanh, x\u00b2, x\u00b3, |x|, \u043a\u0443\u0441\u043e\u0447\u043d\u043e-\u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0435); \u2113_m \u2014 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435 \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u044b \u043e\u0431\u0449\u0438\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b; e_j \u2014 \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u044b\u0435 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u0448\u0443\u043c\u044b (\u041b\u0430\u043f\u043b\u0430\u0441(\u03c3), \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u0430\u044f \u0440\u0430\u0432\u043d\u043e\u043c\u0435\u0440\u043d\u0430\u044f \u0441\u043c\u0435\u0441\u044c, \u0438\u043b\u0438 \u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u044f exp).\n\u0418\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u043e\u0441\u0442\u044c (\u043f\u043e Maeda & Shimodaira):\n  I1. \u0412\u0441\u0435 e_j \u0438 \u2113_m \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u044b, \u0432\u0437\u0430\u0438\u043c\u043d\u043e \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b \u0438 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b \u043c\u0435\u0436\u0434\u0443 \u0441\u043e\u0431\u043e\u0439.\n  I2. \u041b\u044e\u0431\u0430\u044f \u043f\u0430\u0440\u0430 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445 \u0438\u043c\u0435\u0435\u0442 \u043d\u0435 \u0431\u043e\u043b\u0435\u0435 \u043e\u0434\u043d\u043e\u0439 \u043e\u0431\u0449\u0435\u0439 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0439 \u043f\u0440\u0438\u0447\u0438\u043d\u044b.\n  I3. \u041d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0435 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0435 \u043e\u0431\u0440\u0430\u0437\u0443\u044e\u0442 DAG; \u0430\u0434\u0434\u0438\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u0432.\n\u0412\u044b\u0445\u043e\u0434 CAM-UV: \u043c\u0430\u0442\u0440\u0438\u0446\u0430 A \u0441 \u043a\u043e\u0434\u0430\u043c\u0438: 0 \u2014 \u043d\u0435\u0442 \u0441\u0432\u044f\u0437\u0438; 1/2 \u2014 \u043f\u0440\u044f\u043c\u043e\u0435 \u0440\u0435\u0431\u0440\u043e i\u2192j / j\u2192i (B-\u0441\u043c\u0435\u0436\u043d\u043e\u0441\u0442\u044c); 3 \u2014 \u043f\u0430\u0440\u0430 \u0441\u043e \u0441\u043a\u0440\u044b\u0442\u043e\u0439 \u043e\u0431\u0449\u0435\u0439 \u043f\u0440\u0438\u0447\u0438\u043d\u043e\u0439 (N-\u0441\u043c\u0435\u0436\u043d\u043e\u0441\u0442\u044c).\n\n======================================================================\n2. \u0413\u0415\u041d\u0415\u0420\u0410\u0422\u041e\u0420 \u0414\u0410\u041d\u041d\u042b\u0425 (\u043f\u043e\u043b\u043d\u0430\u044f \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f)\n======================================================================\n2.1. \u041f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u044b \u0441\u0435\u0442\u043a\u0438: p \u2208 {5, 10, 20}; n \u2208 {500, 1000, 5000}; \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 R = 100 \u043d\u0430 \u044f\u0447\u0435\u0439\u043a\u0443; \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435 \u0444\u0430\u043a\u0442\u043e\u0440\u044b L \u2208 {0, 1, 3} (0 = \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0431\u0435\u0437 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u043e\u0432); \u0441\u0438\u043b\u0430 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u0432 \u03bb \u2208 {0.5, 1.5}\u00b7\u03c3_\u0448\u0443\u043c\u0430.\n2.2. DAG: \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445; \u0440\u0451\u0431\u0440\u0430 i\u2192j (i<j \u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0435) \u0441 \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e\u0441\u0442\u044c\u044e q, q \u0432\u044b\u0431\u0440\u0430\u043d\u043e \u0442\u0430\u043a, \u0447\u0442\u043e\u0431\u044b \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u0447\u0438\u0441\u043b\u043e \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 \u043d\u0430 \u0443\u0437\u0435\u043b \u2248 {1, 2} (\u0434\u0432\u0430 \u043f\u043e\u0434\u0443\u0441\u043b\u043e\u0432\u0438\u044f \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438).\n2.3. \u041b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435 \u0444\u0430\u043a\u0442\u043e\u0440\u044b: L \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432 \u2113_m ~ \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e (\u0442\u043e \u0436\u0435 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e, \u0447\u0442\u043e \u0448\u0443\u043c\u044b), \u043a\u0430\u0436\u0434\u044b\u0439 \u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u043a \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u043e\u043c\u0443 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0443 \u0438\u0437 2\u20134 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445 \u0441 \u0432\u0435\u0441\u0430\u043c\u0438 \u03bb_jm.\n2.4. \u0420\u0415\u0410\u041b\u0418\u0417\u0410\u0426\u0418\u042f \u0423\u0421\u041b\u041e\u0412\u0418\u042f I2 \u00ab\u22641 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0439 \u043f\u0440\u0438\u0447\u0438\u043d\u044b \u043d\u0430 \u043f\u0430\u0440\u0443\u00bb (\u044f\u0432\u043d\u043e, \u043f\u043e \u0432\u0430\u0448\u0435\u0439 \u043f\u0440\u0430\u0432\u043a\u0435 (1)):\n  - \u041f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0435 \u0438\u043d\u0446\u0438\u0434\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u0438: \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0444\u0430\u043a\u0442\u043e\u0440\u0430 m \u0441\u043e\u0437\u0434\u0430\u0451\u043c \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e S_m \u2286 {1..p}, |S_m| \u2208 {2,3,4}; \u0437\u0430\u0442\u0435\u043c \u043f\u0440\u0438\u043c\u0435\u043d\u044f\u0435\u043c \u043f\u0440\u043e\u0446\u0435\u0434\u0443\u0440\u0443 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043d\u0438\u044f \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442\u043e\u0432: \u0435\u0441\u043b\u0438 \u043f\u0430\u0440\u0430 (i,j) \u043f\u043e\u043f\u0430\u0434\u0430\u0435\u0442 \u0432 \u0434\u0432\u0430 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 S_m, S_m', m' > m, \u0443\u0434\u0430\u043b\u044f\u0435\u043c \u043f\u0430\u0440\u0443 \u0438\u0437 S_m' (\u0436\u0430\u0434\u043d\u043e, \u0432 \u043f\u043e\u0440\u044f\u0434\u043a\u0435 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u0430 \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432) \u0438 \u043f\u0435\u0440\u0435-\u043f\u043e\u0434\u043a\u043b\u044e\u0447\u0430\u0435\u043c \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u044e\u0449\u0438\u0435 \u0443\u0437\u043b\u044b m' \u043a \u043f\u0430\u0440\u0430\u043c, \u0435\u0449\u0451 \u043d\u0435 \u043f\u043e\u043a\u0440\u044b\u0442\u044b\u043c \u043d\u0438 \u043e\u0434\u043d\u0438\u043c \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u043c. \u0426\u0438\u043a\u043b \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442\u0441\u044f \u0434\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044f \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0430; \u043f\u043e\u0441\u043b\u0435 \u0447\u0435\u0433\u043e \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0444\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u0430\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430: \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043f\u0430\u0440 |{m : i,j \u2208 S_m}| \u2264 1 \u2014 \u0438\u043d\u0430\u0447\u0435 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u043f\u0435\u0440\u0435\u0437\u0430\u043f\u0443\u0441\u043a\u0430\u0435\u0442 \u0441\u0435\u043c\u043f\u043b DAG (\u0441\u0447\u0451\u0442\u0447\u0438\u043a \u043e\u0442\u043a\u0430\u0437\u043e\u0432 \u043b\u043e\u0433\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0434\u0438\u0430\u0433\u043d\u043e\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430).\n  - \u042d\u0442\u043e \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u2014 \u0447\u0430\u0441\u0442\u044c \u043e\u0431\u043b\u0430\u0441\u0442\u0438 \u0438\u0434\u0435\u043d\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u0443\u0435\u043c\u043e\u0441\u0442\u0438 CAM-UV; \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0435 \u0441\u0442\u0440\u0435\u0441\u0441-\u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u0441 \u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435\u043c I2 \u041d\u0415 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043e\u0441\u043d\u043e\u0432\u043d\u0443\u044e \u0441\u0435\u0442\u043a\u0443 (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u043a\u0430\u043a \u043e\u0441\u043e\u0437\u043d\u0430\u043d\u043d\u043e\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u0438).\n2.5. Ground truth \u0438 \u0435\u0433\u043e \u0432\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f (\u043f\u043e \u0432\u0430\u0448\u0435\u0439 \u043f\u0440\u0430\u0432\u043a\u0435 (1)):\n  - \u0413\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440 \u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u0443\u0435\u0442: GT_B \u2014 \u0431\u0438\u043d\u0430\u0440\u043d\u0443\u044e \u043c\u0430\u0442\u0440\u0438\u0446\u0443 \u043f\u0440\u044f\u043c\u044b\u0445 \u0440\u0451\u0431\u0435\u0440 (p\u00d7p, \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435), GT_N \u2014 \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u0443\u044e \u043c\u0430\u0442\u0440\u0438\u0446\u0443 \u043f\u0430\u0440 \u0441 \u043e\u0431\u0449\u0435\u0439 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0439 \u043f\u0440\u0438\u0447\u0438\u043d\u043e\u0439, \u0438 \u0441\u043f\u0438\u0441\u043e\u043a \u043f\u0430\u0440\u0430\u043c\u0435\u0442\u0440\u043e\u0432 \u0432\u0441\u0435\u0445 f_jk, \u03bb, \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432.\n  - \u0412\u0430\u043b\u0438\u0434\u0430\u0446\u0438\u044f \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u044f: (a) \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u0430\u044f \u2014 \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u0438 DAG \u0440\u0435\u0431\u0440\u043e \u0434\u043e\u0431\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0432 GT_B \u043e\u0434\u043d\u043e\u0432\u0440\u0435\u043c\u0435\u043d\u043d\u043e \u0441 \u0441\u0435\u043c\u043f\u043b\u0435\u0440\u043e\u043c (\u0435\u0434\u0438\u043d\u044b\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0438\u0441\u0442\u0438\u043d\u044b, \u0430 \u043d\u0435 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u00ab\u043c\u0435\u0442\u0440\u0438\u0447\u0435\u0441\u043a\u0430\u044f\u00bb \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430); (b) \u043f\u043e\u0432\u0435\u0434\u0435\u043d\u0447\u0435\u0441\u043a\u0430\u044f \u2014 \u0441\u0430\u043d\u0438\u0442\u0438-\u0447\u0435\u043a \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430: \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430 \u0438\u0437 10 \u044f\u0447\u0435\u0435\u043a \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043e\u0442\u043a\u0430\u0442\u043e\u043c \u0441\u0435\u043c\u043f\u043b\u0435\u0440\u0430 (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f x_j \u043d\u0430 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 + \u0444\u0430\u043a\u0442\u043e\u0440\u044b \u0434\u0430\u0451\u0442 \u043d\u0443\u043b\u0435\u0432\u044b\u0435 \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u043c f_jk \u2014 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u043e\u0441\u0442\u0438 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438, \u043d\u0435 \u0442\u043e\u0436\u0434\u0435\u0441\u0442\u0432\u043e); (c) \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442 I2 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u043d\u043e \u043d\u0430 \u043a\u0430\u0436\u0434\u043e\u043c \u0441\u0435\u043c\u043f\u043b\u0435 (assert, \u043e\u0442\u043a\u0430\u0437 \u2192 \u043f\u0435\u0440\u0435\u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f).\n2.6. \u0428\u0443\u043c: e_j ~ \u0432\u044b\u0431\u0440\u0430\u043d\u043d\u044b\u0439 \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432 \u0437\u0430\u043a\u043e\u043d \u0441 \u03c3_j ~ U[0.5, 2]; \u0441\u0442\u0430\u043d\u0434\u0430\u0440\u0442\u0438\u0437\u0430\u0446\u0438\u044f \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u0435\u0442\u0441\u044f \u0434\u043e \u043e\u0446\u0435\u043d\u043a\u0438 (CAM-UV \u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u0435\u043d \u043a \u043c\u0430\u0441\u0448\u0442\u0430\u0431\u0443 \u0447\u0435\u0440\u0435\u0437 ICA-\u0441\u0442\u0430\u0434\u0438\u044e \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u043a\u0430\u043a \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u0435 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438).\n2.7. \u0413\u0430\u0443\u0441\u0441\u043e\u0432 \u043d\u0435\u0433\u0430\u0442\u0438\u0432\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c: \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u0430\u044f \u0432\u0435\u0442\u043a\u0430 \u0441 e_j, \u2113_m ~ N(0, \u03c3) \u2014 \u043e\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044f \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f CAM-UV (\u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435 I1); \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u0435 \u0440\u043e\u043b\u0438 \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u0438, \u043d\u0435 \u043a\u0430\u043a \u00ab\u0441\u0431\u043e\u0439\u00bb.\n\n======================================================================\n3. \u0410\u041b\u0413\u041e\u0420\u0418\u0422\u041c CAM-UV \u041f\u041e \u0428\u0410\u0413\u0410\u041c (\u0441\u043f\u0435\u0446\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438)\n======================================================================\n\u0428\u0430\u0433 1. \u041e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u0435 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u043e\u0431\u0449\u0438\u0445 \u043f\u0440\u0438\u0447\u0438\u043d.\n  1.1. Whitening: \u0446\u0435\u043d\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435; \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0440\u0430\u0437\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0446\u0438\u0438 \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u0442\u0441\u044f \u0432\u0440\u0443\u0447\u043d\u0443\u044e (power iteration/Jacobi \u043d\u0430 \u0447\u0438\u0441\u0442\u043e\u043c Python \u2014 \u043c\u0435\u0434\u043b\u0435\u043d\u043d\u043e, \u0441\u043c. \u00a77).\n  1.2. Overcomplete ICA: \u0438\u0449\u0435\u043c p' = p + L_max \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0445 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442 (L_max = 4) \u043c\u0435\u0442\u043e\u0434\u043e\u043c, \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u044b\u043c \u0441\u043e stdlib: FastICA-\u043f\u043e\u0434\u043e\u0431\u043d\u0430\u044f \u0438\u0442\u0435\u0440\u0430\u0446\u0438\u044f \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0442\u043e\u0447\u043a\u043e\u0439 \u043d\u0430 \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432\u043e\u0441\u0442\u0438 (kurtosis/|tanh| contrast) \u2014 \u0443\u043f\u0440\u043e\u0449\u0451\u043d\u043d\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f; \u044d\u0442\u043e \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u043e\u0442 \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b\u0430 (\u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442 overcomplete JADE/FOBI).\n  1.3. \u0414\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u0432\u044b\u0434\u0435\u043b\u0435\u043d\u043d\u043e\u0439 \u043a\u043e\u043c\u043f\u043e\u043d\u0435\u043d\u0442\u044b s: \u0435\u0441\u043b\u0438 s \u0432\u044b\u0433\u043b\u044f\u0434\u0438\u0442 \u00ab\u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0439\u00bb (\u043c\u0430\u043b\u0430 \u0434\u0438\u0441\u043f\u0435\u0440\u0441\u0438\u044f \u043e\u0431\u044a\u044f\u0441\u043d\u0451\u043d\u043d\u043e\u0439 \u043e\u0434\u043d\u0438\u043c \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u043c \u0443\u0437\u043b\u043e\u043c / \u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u043d\u043e\u0441\u0442\u0438 \u0441\u043e\u0441\u0440\u0435\u0434\u043e\u0442\u043e\u0447\u0435\u043d\u044b \u043d\u0430 \u22652 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u044b\u0445), \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u043c \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u0430-\u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u0430 \u0438 \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u043c \u0432\u0441\u0435 \u043f\u0430\u0440\u044b \u0443\u0437\u043b\u043e\u0432 \u0441 \u0437\u043d\u0430\u0447\u0438\u043c\u044b\u043c\u0438 \u0437\u0430\u0433\u0440\u0443\u0437\u043a\u0430\u043c\u0438 \u043d\u0430 s \u043a\u0430\u043a N-\u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432.\n\u0428\u0430\u0433 2. Parent detection.\n  2.1. \u0414\u043b\u044f \u043f\u0430\u0440 (i, j) \u0431\u0435\u0437 N-\u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u0441\u0442\u0432\u0430: \u043f\u0440\u044f\u043c\u043e\u0439 LiNGAM-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u2014 \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0439 \u043f\u0430\u0440\u044b \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f, \u0447\u044c\u044f \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u0433\u043e \u0434\u0430\u0451\u0442 \u0431\u043e\u043b\u0435\u0435 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u043e\u0441\u0442\u0430\u0442\u043a\u0438; \u0434\u0430\u043b\u0435\u0435 \u043f\u0440\u044f\u043c\u044b\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u044e\u0442\u0441\u044f \u043d\u0435\u043b\u0438\u043d\u0435\u0439\u043d\u043e\u0439 \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u0435\u0439 (\u0432 stdlib \u2014 \u043f\u043e\u043b\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u044c\u043d\u0430\u044f/\u0441\u043f\u043b\u0430\u0439\u043d\u043e\u0432\u0430\u044f \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f \u043c\u0430\u043b\u043e\u0439 \u0441\u0442\u0435\u043f\u0435\u043d\u0438 \u0441 \u0440\u0438\u0434\u0436-\u0440\u0435\u0433\u0443\u043b\u044f\u0440\u0438\u0437\u0430\u0446\u0438\u0435\u0439, \u0440\u0435\u0448\u0430\u0435\u043c\u0430\u044f \u0432\u0440\u0443\u0447\u043d\u0443\u044e \u0447\u0435\u0440\u0435\u0437 \u043d\u043e\u0440\u043c\u0430\u043b\u044c\u043d\u044b\u0435 \u0443\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043d\u0430 \u043c\u0430\u043b\u044b\u0445 \u043c\u0430\u0442\u0440\u0438\u0446\u0430\u0445) \u0441 \u0442\u0435\u0441\u0442\u043e\u043c \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0441\u0442\u0430\u0442\u043a\u043e\u0432.\n  2.2. \u0414\u043b\u044f N-\u043f\u0430\u0440 (i, j): \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u044b-\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438 j \u0434\u043b\u044f i \u2014 \u0432\u0441\u0435 \u0443\u0437\u043b\u044b, \u043a\u0440\u043e\u043c\u0435 j \u0438 \u0438\u043c\u0435\u044e\u0449\u0438\u0445 N-\u0441\u043c\u0435\u0436\u043d\u043e\u0441\u0442\u044c \u0441 i; \u0438\u0437 x_i \u0432\u044b\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0432\u043a\u043b\u0430\u0434 \u043e\u0446\u0435\u043d\u0451\u043d\u043d\u044b\u0445 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432 (\u0448\u0430\u0433 1.3), \u0437\u0430\u0442\u0435\u043c \u043d\u0435\u043b\u0438\u043d\u0435\u0439\u043d\u0430\u044f \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f \u043d\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u043e\u0432; \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f, \u0435\u0441\u043b\u0438 \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0435 \u043f\u0440\u0438\u0437\u043d\u0430\u043a\u0438 \u043f\u043e\u0441\u043b\u0435 \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u0438 \u043d\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u0430 \u0438 \u043d\u0430 \u043a\u0430\u043d\u0434\u0438\u0434\u0430\u0442\u0430+j \u0434\u0435\u043c\u043e\u043d\u0441\u0442\u0440\u0438\u0440\u0443\u044e\u0442 \u0437\u043d\u0430\u0447\u0438\u043c\u043e\u0435 \u0441\u043d\u0438\u0436\u0435\u043d\u0438\u0435 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 (\u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u0442\u0438\u043f\u0430 PE/HSI).\n  2.3. \u0422\u0435\u0441\u0442 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0441\u0442\u0430\u0442\u043a\u043e\u0432: \u0431\u0430\u0437\u043e\u0432\u044b\u0439 \u043f\u0440\u043e\u043a\u0441\u0438 \u2014 \u0440\u0430\u0441\u0441\u0442\u043e\u044f\u043d\u0438\u0435-\u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u044f (dCor) \u043d\u0430 \u0447\u0438\u0441\u0442\u043e\u043c Python (O(n\u00b2) \u2014 \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u043e \u043f\u0440\u0438 n \u2264 5000 \u0441 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u043e\u0439) \u0418\u041b\u0418 HSI-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 kernel-\u0442\u0435\u0441\u0442; \u041f\u041e\u041c\u0415\u0422\u041a\u0410 (\u043f\u043e U5): \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u043f\u0440\u043e\u043a\u0441\u0438-\u0442\u0435\u0441\u0442, \u043d\u0435 \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 HSI \u0441\u0442\u0430\u0442\u044c\u0438 \u2192 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u0438: \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u0435 \u0443\u0440\u043e\u0432\u043d\u0438 precision/recall \u043c\u043e\u0433\u0443\u0442 \u043e\u0442\u043b\u0438\u0447\u0430\u0442\u044c\u0441\u044f \u043e\u0442 \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0445, \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043c\u0435\u0436\u0434\u0443 \u043c\u0435\u0442\u043e\u0434\u0430\u043c\u0438 \u0432\u043d\u0443\u0442\u0440\u0438 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0432\u0430\u043b\u0438\u0434\u043d\u044b\u043c\u0438.\n\u041f\u0441\u0435\u0432\u0434\u043e\u043a\u043e\u0434 (\u0441\u0436\u0430\u0442\u044b\u0439):\n  input X (n\u00d7p)\n  Z = whiten(X); S = overcomplete_ICA(Z, p+L_max)\n  N_cand = pairs_with_common_loaded_factor(S, \u03bb-\u043f\u043e\u0440\u043e\u0433)\n  B = zeros(p,p)\n  for (i,j) in pairs not in N_cand:\n      order via pairwise residual-independence (LiNGAM-like)\n      for each variable in order: parents = {k : residual-dep(x_i | parents\u222a{k}) significantly < residual-dep(x_i | parents)}\n  for (i,j) in N_cand:\n      lat = subtract_latent_contributions(X, S)\n      for target i: test candidates as in 2.2 \u2192 direct parents of i among {k \\ j}\n  output A (0/1/2/3)\n\n======================================================================\n4. \u0411\u0415\u0419\u0421\u041b\u0410\u0419\u041d\u042b (\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043e \u043f\u043e U3)\n======================================================================\n  B1. DirectLiNGAM (\u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432, \u043d\u0435 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435) \u2014 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0441 \u043d\u0443\u043b\u044f.\n  B2. PC / \u043f\u043e\u0440\u044f\u0434\u043a\u043e\u0432\u044b\u0439 PC-\u043f\u043e\u0434\u043e\u0431\u043d\u044b\u0439 \u043c\u0435\u0442\u043e\u0434 (\u0443\u0441\u043b\u043e\u0432\u043d\u0430\u044f \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u044c \u043f\u043e \u0447\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0439 \u043a\u043e\u0440\u0440\u0435\u043b\u044f\u0446\u0438\u0438).\n  B3. Ablation: CAM-UV \u0431\u0435\u0437 \u0448\u0430\u0433\u0430 1 (parent detection \u043d\u0430 \u0441\u044b\u0440\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445) \u2014 \u0438\u0437\u043e\u043b\u0438\u0440\u0443\u0435\u0442 \u0432\u043a\u043b\u0430\u0434 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u043e\u0439 \u0441\u0442\u0430\u0434\u0438\u0438.\n\u0418\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u044f (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c, \u044d\u0442\u043e \u0447\u0430\u0441\u0442\u044c \u0432\u044b\u0432\u043e\u0434\u043e\u0432, \u043d\u0435 \u043e\u043f\u0440\u0430\u0432\u0434\u0430\u043d\u0438\u0435): B1\u2013B3 \u043d\u0435 \u043c\u043e\u0434\u0435\u043b\u0438\u0440\u0443\u044e\u0442 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0435 \u043e\u0431\u0449\u0438\u0435 \u043f\u0440\u0438\u0447\u0438\u043d\u044b, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043d\u0430 N-\u043f\u0430\u0440\u0430\u0445 \u043e\u043d\u0438 \u0430\u043f\u0440\u0438\u043e\u0440\u0438 \u043d\u0435 \u043c\u043e\u0433\u0443\u0442 \u0434\u0430\u0432\u0430\u0442\u044c \u043f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0438 \u043e\u0436\u0438\u0434\u0430\u044e\u0442\u0441\u044f \u0441\u043b\u0430\u0431\u0435\u0435; \u0438\u0445 \u0440\u043e\u043b\u044c \u2014 \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c, \u0447\u0442\u043e B-\u0440\u0451\u0431\u0440\u0430 CAM-UV \u043d\u0435 \u0434\u0435\u0433\u0440\u0430\u0434\u0438\u0440\u0443\u044e\u0442 \u043f\u0440\u0438 \u043d\u0430\u043b\u0438\u0447\u0438\u0438 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u043e\u0432, \u0430 \u043d\u0435 \u00ab\u043f\u043e\u0431\u0435\u0434\u0438\u0442\u044c\u00bb \u043d\u0430 N-\u043c\u0435\u0442\u0440\u0438\u043a\u0435. \u0412\u0441\u0435 \u0431\u0435\u0439\u0441\u043b\u0430\u0439\u043d\u044b \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u0442\u0435\u0445 \u0436\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u043c\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 (\u0431\u0435\u0437 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u2113).\n\n======================================================================\n5. \u041c\u0415\u0422\u0420\u0418\u041a\u0418 (\u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e true vs extra, \u043a\u0430\u043a \u0437\u0430\u043f\u0440\u043e\u0448\u0435\u043d\u043e)\n======================================================================\n  - B-\u0440\u0451\u0431\u0440\u0430: precision_B = TP_B/(TP_B+FP_B) (TP/FP \u043f\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u043c \u0440\u0451\u0431\u0440\u0430\u043c), recall_B, F1_B; \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e extra edges (FP_B) \u0438 missing edges.\n  - N-\u043f\u0430\u0440\u044b: precision_N = TP_N/(TP_N+FP_N), recall_N, F1_N; FP_N \u2014 \u00ab\u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435\u00bb \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u044b (\u043a\u043b\u044e\u0447\u0435\u0432\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u043d\u0430 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435 L=0).\n  - \u041f\u0435\u0440\u0435\u043a\u0440\u0451\u0441\u0442\u043d\u044b\u0435 \u043e\u0448\u0438\u0431\u043a\u0438: \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u043d\u043e\u0435 \u043f\u0440\u044f\u043c\u043e\u0435 \u0440\u0435\u0431\u0440\u043e \u0442\u0430\u043c, \u0433\u0434\u0435 truth = N-\u043f\u0430\u0440\u0430 (\u0438 \u043d\u0430\u043e\u0431\u043e\u0440\u043e\u0442) \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0441\u0447\u0451\u0442\u0447\u0438\u043a confusion_BN.\n  - \u0421\u0443\u043c\u043c\u0430\u0440\u043d\u043e: SHD \u043f\u043e \u043e\u0431\u044a\u0435\u0434\u0438\u043d\u0451\u043d\u043d\u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435.\n  - \u041e\u0442\u0447\u0451\u0442: \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u00b1 std \u043f\u043e 100 \u043f\u043e\u0432\u0442\u043e\u0440\u0430\u043c; \u043f\u0440\u0438 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 (\u00a77) \u2014 \u043c\u0435\u0434\u0438\u0430\u043d\u0430 \u0438 IQR.\n\n======================================================================\n6. \u041a\u041e\u041d\u0422\u0420\u041e\u041b\u0418\u0420\u0423\u0415\u041c\u042b\u0415 \u0423\u0421\u041b\u041e\u0412\u0418\u042f\n  C1. L=0, \u043d\u0435\u0433\u0430\u0443\u0441\u0441\u043e\u0432 \u0448\u0443\u043c: CAM-UV \u043d\u0435 \u0434\u043e\u043b\u0436\u0435\u043d \u0432\u044b\u0434\u0430\u0432\u0430\u0442\u044c N-\u043f\u0430\u0440 (FP_N \u2014 \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0438\u043d\u0434\u0438\u043a\u0430\u0442\u043e\u0440).\n  C2. \u0413\u0430\u0443\u0441\u0441\u043e\u0432 \u0448\u0443\u043c/\u0444\u0430\u043a\u0442\u043e\u0440\u044b (\u043d\u0430\u0440\u0443\u0448\u0435\u043d\u0438\u0435 I1): \u043e\u0436\u0438\u0434\u0430\u0435\u043c\u0430\u044f \u0434\u0435\u0433\u0440\u0430\u0434\u0430\u0446\u0438\u044f \u043e\u0431\u043e\u0438\u0445 \u0442\u0438\u043f\u043e\u0432.\n  C3. \u03bb \u043c\u0430\u043b\u0430\u044f (\u0441\u043b\u0430\u0431\u044b\u0435 \u043a\u043e\u043d\u0444\u0430\u0443\u043d\u0434\u0435\u0440\u044b): \u0433\u0440\u0430\u043d\u0438\u0446\u0430 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438.\n  C4. \u0423\u0432\u0435\u043b\u0438\u0447\u0435\u043d\u043d\u043e\u0435 \u0447\u0438\u0441\u043b\u043e \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 (q-\u0432\u0430\u0440\u0438\u0430\u043d\u0442): \u0432\u043b\u0438\u044f\u043d\u0438\u0435 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 DAG.\n\n======================================================================\n7. \u041f\u041b\u0410\u041d \u0410\u041d\u0410\u041b\u0418\u0417\u0410, \u041f\u041e\u0420\u041e\u0413\u0418 \u0418 \u0412\u042b\u0427\u0418\u0421\u041b\u0418\u0422\u0415\u041b\u042c\u041d\u0410\u042f \u041e\u0426\u0415\u041d\u041a\u0410\n======================================================================\n7.1. \u041f\u043e\u0440\u043e\u0433\u0438 \u0440\u0435\u0448\u0430\u044e\u0449\u0438\u0445 \u043f\u0440\u0430\u0432\u0438\u043b (\u043f\u043e \u0432\u0430\u0448\u0435\u0439 \u043f\u0440\u0430\u0432\u043a\u0435 (2)):\n  - \u0412\u0441\u0435 \u0442\u0435\u0441\u0442\u044b (ICA-\u0437\u0430\u0433\u0440\u0443\u0436\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u043e\u0441\u0442\u0430\u0442\u043a\u043e\u0432, \u0432\u044b\u0431\u043e\u0440\u0430 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f) \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442 \u03b1-\u043f\u043e\u0440\u043e\u0433\u0438, \u0432\u044b\u0431\u0438\u0440\u0430\u0435\u043c\u044b\u0435 \u041e\u0414\u0418\u041d \u0440\u0430\u0437 \u043d\u0430 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u043c \u043a\u0430\u043b\u0438\u0431\u0440\u043e\u0432\u043e\u0447\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435 (\u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0435 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0441\u0435\u043c\u043f\u043b\u044b, p=10, n=1000, L=1) \u043f\u043e \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u044e \u043c\u0430\u043a\u0441\u0438\u043c\u0438\u0437\u0430\u0446\u0438\u0438 F1_N \u043f\u0440\u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0438 FP_N \u2264 \u043a\u0432\u0430\u043d\u0442\u0438\u043b\u044c \u043d\u0430 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u043e\u043c C1 \u2014 \u0437\u0430\u0442\u0435\u043c \u0437\u0430\u043c\u043e\u0440\u0430\u0436\u0438\u0432\u0430\u044e\u0442\u0441\u044f \u0434\u043b\u044f \u0432\u0441\u0435\u0445 \u043e\u0441\u043d\u043e\u0432\u043d\u044b\u0445 \u043f\u0440\u043e\u0433\u043e\u043d\u043e\u0432. \u042d\u0442\u043e \u0443\u0441\u0442\u0440\u0430\u043d\u044f\u0435\u0442 \u043d\u0435\u044f\u0432\u043d\u044b\u0439 \u0442\u044e\u043d\u0438\u043d\u0433 \u043d\u0430 \u0442\u0435\u0441\u0442\u043e\u0432\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445.\n  - \u0410\u043d\u0430\u043b\u0438\u0437 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438: \u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0441\u0435\u0442\u043a\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435 (p=10, n=1000, L\u2208{1,3}) \u0441 \u03b1 \u2208 {0.01, 0.05, 0.1} \u0438 \u043f\u043e\u0440\u043e\u0433\u043e\u043c dCor \u2208 {0.05, 0.1}; \u043e\u0442\u0447\u0438\u0442\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u043a\u0440\u0438\u0432\u044b\u0435 F1_B, F1_N vs \u03b1 \u2014 \u0447\u0442\u043e\u0431\u044b \u043f\u043e\u043a\u0430\u0437\u0430\u0442\u044c \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u044c/\u043d\u0435\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u044c \u0432\u044b\u0432\u043e\u0434\u043e\u0432 \u043a \u043f\u043e\u0440\u043e\u0433\u0443.\n7.2. \u0412\u044b\u0447\u0438\u0441\u043b\u0438\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430 (stdlib, \u0431\u0435\u0437 BLAS):\n  - \u0414\u043e\u043c\u0438\u043d\u0438\u0440\u0443\u044e\u0449\u0438\u0435 \u0437\u0430\u0442\u0440\u0430\u0442\u044b: ICA-\u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0438 O(iter\u00b7p'\u00b3) \u0432\u0440\u0443\u0447\u043d\u0443\u044e, dCor O(n\u00b2\u00b7pairs) = O(n\u00b2\u00b7p\u00b2) \u043d\u0430 \u043f\u0435\u0440\u0435\u043c\u0435\u043d\u043d\u0443\u044e; \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u043b\u044f p=20, n=5000: ~ (5000\u00b2 \u00b7 190 \u043f\u0430\u0440 \u00b7 ~10 \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u0439) \u2248 5\u00b710^9 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u0430\u0440\u043d\u044b\u0445 \u043e\u043f\u0435\u0440\u0430\u0446\u0438\u0439 \u043d\u0430 \u0441\u0435\u043c\u043f\u043b \u2192 \u043d\u0430 \u0447\u0438\u0441\u0442\u043e\u043c Python \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0434\u0435\u0441\u044f\u0442\u043a\u043e\u0432 \u043c\u0438\u043d\u0443\u0442 \u043d\u0430 \u0441\u0435\u043c\u043f\u043b \u2192 \u043f\u043e\u043b\u043d\u0430\u044f \u0441\u0435\u0442\u043a\u0430 (27 \u044f\u0447\u0435\u0435\u043a \u00d7 100 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u00d7 4 \u043c\u0435\u0442\u043e\u0434\u0430) \u043d\u0435\u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u0430 \u0432 \u043f\u043e\u043b\u043d\u043e\u043c \u043e\u0431\u044a\u0451\u043c\u0435.\n  - \u041f\u043e\u0440\u044f\u0434\u043e\u043a \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0439 \u043f\u0440\u0438 \u0443\u043f\u043e\u0440\u0435 \u0432 \u0431\u044e\u0434\u0436\u0435\u0442 (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c \u0437\u0430\u0440\u0430\u043d\u0435\u0435): (1) \u0441\u043d\u0430\u0447\u0430\u043b\u0430 \u0440\u0435\u0436\u0435\u043c \u043f\u043e\u0432\u0442\u043e\u0440\u044b \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 p\u00b7n: p=20/n=5000 \u2192 25 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432; (2) \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430 n=2000 \u0432\u043d\u0443\u0442\u0440\u0438 dCor (dCor \u043d\u0430 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u0439 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435, \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u0430\u043f\u043f\u0440\u043e\u043a\u0441\u0438\u043c\u0430\u0446\u0438\u044f); (3) \u0432\u0435\u043a\u0442\u043e\u0440\u0438\u0437\u0430\u0446\u0438\u044f \u0447\u0435\u0440\u0435\u0437 array-\u043c\u043e\u0434\u0443\u043b\u044c/\u0440\u0443\u0447\u043d\u044b\u0435 \u0441\u043f\u0438\u0441\u043a\u0438 \u043d\u0435 \u0441\u043f\u0430\u0441\u0430\u0435\u0442 \u2014 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u044f \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432, \u041d\u0415 \u0440\u0430\u0437\u043c\u0435\u0440\u0430 p \u0438\u043b\u0438 n; (4) 224 \u044f\u0434\u0440\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b, \u043d\u043e stdlib-\u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u0438\u0437\u043c \u0447\u0435\u0440\u0435\u0437 multiprocessing \u0434\u0430\u0451\u0442 ~\u043b\u0438\u043d\u0435\u0439\u043d\u044b\u0439 \u0432\u044b\u0438\u0433\u0440\u044b\u0448 \u2014 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u0432 \u043e\u0446\u0435\u043d\u043a\u0435, \u043d\u0435 \u0432 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438.\n7.3. \u0410\u043d\u0430\u043b\u0438\u0437 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432: 2D-\u0442\u0430\u0431\u043b\u0438\u0446\u044b (p \u00d7 n) \u043f\u043e \u043c\u0435\u0442\u0440\u0438\u043a\u0430\u043c \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u043c\u0435\u0442\u043e\u0434\u0430; \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 CAM-UV vs B1\u2013B3 \u043f\u043e F1_N (\u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441) \u0438 F1_B (\u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430, \u0447\u0442\u043e \u043c\u043e\u0434\u0435\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u043d\u0435 \u0440\u0430\u0437\u0440\u0443\u0448\u0430\u0435\u0442 \u043f\u0440\u044f\u043c\u044b\u0435 \u0440\u0451\u0431\u0440\u0430); \u044d\u0444\u0444\u0435\u043a\u0442\u044b L \u0438 \u03bb; \u0433\u0430\u0443\u0441\u0441\u043e\u0432 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043a\u0430\u043a \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0434\u043e\u043f\u0443\u0449\u0435\u043d\u0438\u044f.\n\n======================================================================\n8. \u041e\u041f\u0426\u0418\u041e\u041d\u0410\u041b\u042c\u041d\u041e\u0415 \u0420\u0410\u0421\u0428\u0418\u0420\u0415\u041d\u0418\u0415: \u0420\u0415\u0410\u041b\u042c\u041d\u042b\u0415 \u0414\u0410\u041d\u041d\u042b\u0415 (\u043f\u043e U2 \u2014 \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u043e, \u0434\u0430\u043d\u043d\u044b\u0435 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442)\n======================================================================\n\u041f\u043e\u0434\u0445\u043e\u0434\u044f\u0449\u0438\u0439 \u0442\u0438\u043f \u043d\u0430\u0431\u043e\u0440\u0430: \u0434\u0430\u043d\u043d\u044b\u0435 \u0441 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u043d\u044b\u043c\u0438 \u0441\u043a\u0440\u044b\u0442\u044b\u043c\u0438 \u043e\u0431\u0449\u0438\u043c\u0438 \u043f\u0440\u0438\u0447\u0438\u043d\u0430\u043c\u0438 \u0438 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0439 \u0438\u043b\u0438 \u0441\u043f\u043e\u0440\u043d\u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043e\u0439 (\u043a\u043b\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0440\u0438\u043c\u0435\u0440\u044b: \u0441\u043e\u0446\u0438\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435/\u044d\u043a\u043e\u043d\u043e\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0430\u043d\u0435\u043b\u0438, \u0433\u0434\u0435 \u043e\u0431\u0449\u0430\u044f \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u0430\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430 \u0442\u0438\u043f\u0430 \u00ab\u043e\u0431\u0449\u0438\u0439 \u0444\u0430\u043a\u0442\u043e\u0440 \u0441\u043f\u0440\u043e\u0441\u0430\u00bb \u0438\u043b\u0438 \u00ab\u0441\u0435\u0437\u043e\u043d\u043d\u043e\u0441\u0442\u044c\u00bb \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u044f\u0434\u043e\u0432; \u0438\u043b\u0438 \u0441\u0435\u043d\u0441\u043e\u0440\u043d\u044b\u0435 \u0434\u0430\u043d\u043d\u044b\u0435 \u0441 \u043e\u0431\u0449\u0438\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c). \u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438: ground truth \u043f\u043e B/N \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d \u2192 \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 (\u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u0441 \u0434\u043e\u043c\u0435\u043d\u043d\u044b\u043c\u0438 \u0437\u043d\u0430\u043d\u0438\u044f\u043c\u0438, \u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u043e\u0441\u0442\u044c \u043a \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0430\u043c, bootstrap \u043f\u043e \u0440\u0451\u0431\u0440\u0430\u043c); \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u043d\u0435 \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u0442\u0441\u044f \u0432 \u043a\u043e\u043b\u0438\u0447\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043c\u0435\u0442\u0440\u0438\u043a\u0438 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0441\u0435\u0442\u043a\u0438. \u0421\u0435\u043a\u0446\u0438\u044f \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0439 \u0438 \u043d\u0435 \u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u0432\u044b\u0432\u043e\u0434.\n\n======================================================================\n9. \u0420\u0418\u0421\u041a\u0418 \u0418 \u041e\u0413\u0420\u0410\u041d\u0418\u0427\u0415\u041d\u0418\u042f\n  R1. \u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0441 \u043d\u0443\u043b\u044f \u043d\u0430 stdlib \u043c\u043e\u0436\u0435\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043e\u0448\u0438\u0431\u043a\u0438 \u0432 ICA/\u0442\u0435\u0441\u0442\u0430\u0445 \u2192 \u043c\u0438\u0442\u0438\u0433\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0441\u0430\u043d\u0438\u0442\u0438-\u0447\u0435\u043a\u0430\u043c\u0438 \u0433\u0435\u043d\u0435\u0440\u0430\u0442\u043e\u0440\u0430 (\u00a72.5b) \u0438 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c\u0438 \u043c\u0430\u043b\u0435\u043d\u044c\u043a\u0438\u043c\u0438 \u043a\u0435\u0439\u0441\u0430\u043c\u0438 \u0441 \u0440\u0443\u0447\u043d\u043e\u0439 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u043e\u0439.\n  R2. \u041f\u0440\u043e\u043a\u0441\u0438-\u0442\u0435\u0441\u0442 \u043d\u0435\u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0438 \u2260 \u043e\u0440\u0438\u0433\u0438\u043d\u0430\u043b\u044c\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u0441\u0442\u0430\u0442\u044c\u0438 (\u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 \u043f\u043e U5) \u2192 \u0432\u043d\u0435\u0448\u043d\u044f\u044f \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u044c \u043f\u043e \u0430\u0431\u0441\u043e\u043b\u044e\u0442\u043d\u044b\u043c \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f\u043c \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0430; \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f \u043e\u0441\u0442\u0430\u044e\u0442\u0441\u044f \u0432\u0430\u043b\u0438\u0434\u043d\u044b.\n  R3. Overcomplete ICA \u043d\u0430 \u0447\u0438\u0441\u0442\u043e\u043c Python \u043d\u0435\u0443\u0441\u0442\u043e\u0439\u0447\u0438\u0432\u0430 \u2192 \u043f\u0440\u0438 \u043d\u0435\u0443\u0434\u0430\u0447\u0435 fallback: \u0434\u0435\u0442\u0435\u043a\u0446\u0438\u044f \u043b\u0430\u0442\u0435\u043d\u0442\u043d\u044b\u0445 \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432 \u0447\u0435\u0440\u0435\u0437 \u0430\u043d\u0430\u043b\u0438\u0437 \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0445 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u043e\u0441\u0442\u0435\u0439 \u043f\u0430\u0440 (\u0443\u043f\u0440\u043e\u0449\u0435\u043d\u0438\u0435, \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e).\n  R4. \u0421\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445 \u0441\u043d\u0438\u0436\u0430\u0435\u0442 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0439 \u2192 \u043e\u0442\u0447\u0451\u0442 \u0441 IQR \u0438 \u044f\u0432\u043d\u043e\u0439 \u043f\u043e\u043c\u0435\u0442\u043a\u043e\u0439 \u044f\u0447\u0435\u0435\u043a \u0441 \u043c\u0435\u043d\u044c\u0448\u0438\u043c \u0447\u0438\u0441\u043b\u043e\u043c \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432.\n  R5. \u0412\u044b\u0432\u043e\u0434\u044b \u043e\u0431 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u044f\u0445 \u0431\u0435\u0439\u0441\u043b\u0430\u0439\u043d\u043e\u0432 \u2014 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0435 (B1\u2013B3 \u043d\u0435 \u043f\u0440\u0435\u0434\u043d\u0430\u0437\u043d\u0430\u0447\u0435\u043d\u044b \u0434\u043b\u044f N-\u043f\u0430\u0440), \u043d\u0435 \u0434\u0435\u0444\u0435\u043a\u0442 \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438.\n\n======================================================================\n10. \u0424\u0415\u0410\u0417\u0418\u0411\u0418\u041b\u0418\u0422\u0418-\u0418\u0422\u041e\u0413\n======================================================================\n\u0420\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u043e \u0432 \u0441\u0440\u0435\u0434\u0435 \u043f\u0440\u0438: (a) \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u043d\u0430 \u0431\u043e\u043b\u044c\u0448\u0438\u0445 \u044f\u0447\u0435\u0439\u043a\u0430\u0445, (b) \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435 \u0432\u043d\u0443\u0442\u0440\u0438 dCor, (c) multiprocessing \u043d\u0430 224 \u044f\u0434\u0440\u0430\u0445. \u041f\u043e\u043b\u043d\u0430\u044f \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u043d\u0430\u044f \u0441\u0435\u0442\u043a\u0430 \u0432 \u00ab\u043c\u0430\u043a\u0441\u0438\u043c\u0430\u043b\u044c\u043d\u043e\u043c\u00bb \u0432\u0438\u0434\u0435 (\u0432\u0441\u0435 \u044f\u0447\u0435\u0439\u043a\u0438 \u00d7 100 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432) \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0439 \u2014 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0439 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d \u0432 \u00a77.2. \u0414\u0438\u0437\u0430\u0439\u043d \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043d; \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u043d\u0435 \u0437\u0430\u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f.", "evidence": "\u041e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435: \u043e\u0441\u043c\u043e\u0442\u0440 /workspace \u2014 \u0442\u043e\u043b\u044c\u043a\u043e task.json (\u0434\u0435\u043a\u043b\u0430\u0440\u0430\u0446\u0438\u044f design-only, \u0440\u0435\u043f\u043e\u0437\u0438\u0442\u043e\u0440\u0438\u0438 \u0438 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u044f \u043d\u0435 \u0442\u0440\u0435\u0431\u0443\u044e\u0442\u0441\u044f); \u043c\u0430\u0442\u0435\u0440\u0438\u0430\u043b\u043e\u0432 CAMUV \u043d\u0435\u0442; stdlib-Only \u0441\u0440\u0435\u0434\u0430 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0430 (import numpy \u2192 ModuleNotFoundError). \u0414\u0438\u0437\u0430\u0439\u043d \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d \u043d\u0430 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u0432\u0430\u043c\u0438 \u0440\u0435\u0448\u0435\u043d\u0438\u044f\u0445: U1 stdlib \u0431\u0435\u0437 pip (\u00a77.2 \u2014 \u043e\u0446\u0435\u043d\u043a\u0430 \u0441\u0442\u043e\u0438\u043c\u043e\u0441\u0442\u0438 \u0438 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0441\u043e\u043a\u0440\u0430\u0449\u0435\u043d\u0438\u0439), U2 \u0441\u0438\u043d\u0442\u0435\u0442\u0438\u043a\u0430 + \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u0430\u044f \u0441\u0435\u043a\u0446\u0438\u044f \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 (\u00a78), U3 DirectLiNGAM+PC+ablation \u0441 \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0435\u0439 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438 \u043f\u043e N-\u043f\u0430\u0440\u0430\u043c (\u00a74), U4 \u0441\u0435\u0442\u043a\u0430 p\u2208{5,10,20}\u00d7n\u2208{500,1000,5000}\u00d7100 \u043f\u043e\u0432\u0442\u043e\u0440\